 * Helper for OpenMP-parallel execution over the outermost dimension of a
 * traverser. The traverser is expected to have been reordered (e.g. using
 * noarr::hoist) so that the desired parallel dimension is outermost.
 *
 * Each OpenMP iteration gets one "inner" traverser with that dimension fixed,
 * then runs a user-provided factory that creates a per-inner-traverser kernel.
 *
 * This keeps:
 *  - all loop structure expressed via Noarr traversers/for_each
 *  - outer dimension parallelized safely
 */
template<typename TraverserT, typename ColumnKernelFactory>
inline void omp_trav_for_each_column(const TraverserT &trav, const ColumnKernelFactory &make_kernel) {
	#pragma omp parallel for schedule(static)
	for (auto inner_trav : trav) {
		// State with indices fixed by this outer traverser (here: the column index 'j')
		auto col_state = inner_trav.state();

		// Build a per-column kernel (captures col_state, alpha, sizes, etc.)
		auto kernel = make_kernel(col_state);

		// Run kernel for all remaining dimensions of this column
		inner_trav.for_each(kernel);
	}
}

// Array initialization
