void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	const std::size_t m_len = A | get_length<'i'>();

	// Traverser over B with 'j' (columns) hoisted to be the outermost dimension.
	// Each element of this traverser in a range-based for will correspond to one
	// fixed column j and will iterate over the rows 'i'.
	auto trav_cols = traverser(B).order(noarr::hoist<'j'>());

	// Factory that, given a column state (fixed 'j'), produces the per-element kernel.
	// The returned lambda will be used inside inner_trav.for_each and gets full
	// (i, j) state for each element in that column.
	auto make_column_kernel = [=, &A, &B](auto col_state) {
		// col_state currently contains the fixed index for 'j' (and no 'i').
		// We capture it by value into the returned lambda so we can cheaply
		// construct B[k][j] states as `col_state + idx<'i'>(k)` inside the k-loop.
		return [=, &A, &B](auto state) {
			// state has both indices 'i' and 'j' for the current element
			const std::size_t i = static_cast<std::size_t>(get_index<'i'>(state));

			// Keep B[i][j] in a register while accumulating over k
			num_t Bij = B[state];

			// k-loop: for (k = i+1; k < M; k++)
			// We strictly follow the original dependence pattern:
			// B[i][j] depends on B[k][j] for k>i; within a column, rows are
			// processed in ascending i, so B[k][j] is still at its original
			// value when we read it here.
			for (std::size_t k = i + 1; k < m_len; ++k) {
				// A[k][i] -> A at (i = k, k = i)
				auto a_state = noarr::idx<'i', 'k'>(k, i);

				// B[k][j] -> same column as col_state, row index k
				auto bkj_state = col_state + noarr::idx<'i'>(k);

				Bij += A[a_state] * B[bkj_state];
			}

			// Final scaling by alpha for this element
			B[state] = Bij * alpha;
		};
	};

	#pragma scop
	// Parallelize across columns 'j'. Each OpenMP iteration gets one inner
	// traverser with fixed 'j' and applies the per-column kernel to all rows.
	omp_trav_for_each_column(trav_cols, make_column_kernel);
	#pragma endscop
