// Original C:
//
// for (i = 0; i < _PB_M; i++)
//   for (j = 0; j < _PB_N; j++) {
//     for (k = i+1; k < _PB_M; k++)
//       B[i][j] += A[k][i] * B[k][j];
//     B[i][j] = alpha * B[i][j];
//   }
//
// A is MxM (i x k), B is MxN (i x j)
//
// Optimized version:
//
// 1) Reorder the triple loop to improve B's memory locality:
//
//    for (k = 0; k < M; k++)
//      for (i = 0; i < k; i++)
//        for (j = 0; j < N; j++)
//          B[i][j] += A[k][i] * B[k][j];
//
//    for (i = 0; i < M; i++)
//      for (j = 0; j < N; j++)
//        B[i][j] *= alpha;
//
//    This is mathematically equivalent to the original:
//    - For each (i,j), contributions A[k][i]*B[k][j] still come in strictly
//      increasing k order.
//    - B[k][j] is always read before any update to B[k][j] that depends on it.
//      Reordering the outer loops therefore does not change which version
//      (original vs. updated) of B[k][j] is used.
//    - The final scaling by alpha is factored out of the k-loop, which is
//      algebraically exact for floating-point: alpha is applied once to the
//      fully accumulated value, just as in the original code.
//    - The order of additions over k for each (i,j) is unchanged, so
//      floating-point rounding is bit-wise identical.
//
// 2) Memory-access improvement:
//
//    In the original code, for fixed (i,j) we walk B[k][j] over k, which is a
//    strided access in row-major storage (i is the outer dimension).
//    In the reordered version, for fixed (k,i) we walk B[i][j] and B[k][j]
//    over j, i.e., we access entire rows contiguously. This is more cache- and
//    SIMD-friendly while preserving the exact arithmetic behavior.
//
[[gnu::flatten, gnu::noinline]]
void kernel_trmm(num_t alpha, auto A, auto B) {
	using namespace noarr;

	// M and N are kept here in case future tuning needs them
	const std::size_t m_len = A | get_length<'i'>();
	const std::size_t n_len = B | get_length<'j'>();
	(void)m_len;
	(void)n_len;

	#pragma scop
	// -------------------------------------------------------------------------
	// Triangular accumulation:
	//   B[i][j] += A[k][i] * B[k][j]  for all 0 <= i < k < M and 0 <= j < N
	//
	// We traverse the union of A and B with dimensions {i, j, k}. We use
	// hoist<'i'> and hoist<'k'> so that the traversal order is:
	//   outer:  k
	//   middle: i
	//   inner:  j
	// -------------------------------------------------------------------------
	noarr::traverser(A, B)
		.order(noarr::hoist<'i'>() ^ noarr::hoist<'k'>())
		.template for_dims<'k'>([=](auto trav_k) {
			// trav_k has 'k' fixed, iterates over 'i' and 'j'
			auto state_k = trav_k.state();
			const std::size_t k = noarr::get_index<'k'>(state_k);

			// For each i < k, we will process the whole row pair (i, k)
			trav_k.template for_dims<'i'>([=](auto trav_ki) {
				auto state_ki = trav_ki.state();
				const std::size_t i = noarr::get_index<'i'>(state_ki);

				// Only use strictly lower-triangular entries A[k][i], i < k
				if (i >= k)
					return;

				// A[k][i]: note that A is laid out as (i, k), so we index as
				//   i_dim = k, k_dim = i.
				const num_t a_ki = A[noarr::idx<'i', 'k'>(k, i)];

				// Inner-most loop over all j:
				//   B[i][j] += A[k][i] * B[k][j]
				//
				// trav_ki has 'k' and 'i' fixed, iterates only 'j'.
				trav_ki.for_each([=](auto state_ijk) {
					// state_ijk contains indices (i, j, k). When indexing B,
					// the extra 'k' dimension is ignored automatically.
					num_t Bij = B[state_ijk]; // B[i][j]

					// Construct a state with the same j but i = k to read B[k][j].
					// We update only the 'i' index; other indices are preserved.
					auto state_kj = noarr::update_index<'i'>(state_ijk, [=](auto) {
						return k;
					});
					const num_t Bkj = B[state_kj]; // B[k][j] (original at this point)

					Bij += a_ki * Bkj;
					B[state_ijk] = Bij; // write back B[i][j]
				});
			});
		});

	// -------------------------------------------------------------------------
	// Final scaling:
	//   B[i][j] = alpha * B[i][j]
	//
	// This is equivalent to the original per-element scaling at the end of the
	// (i,j) loops, but done in a separate pass for better cache and vector
	// behavior and cleaner structure.
	// -------------------------------------------------------------------------
	noarr::traverser(B).for_each([=](auto state) {
		B[state] *= alpha;
	});
	#pragma endscop
