	// in the logical layout is automatically respected.
	traverser(B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed, only 'j' remains varying.
		const auto s_i = trav_i.state();
		const std::size_t i = get_index<'i'>(s_i);

		// Scratch buffer for one horizontal block of row i.
		// The actually used length per iteration is <= J_BLOCK.
		num_t block_buf[J_BLOCK];

		// Walk row i in column blocks [jb, jb + block_len).
		for (std::size_t jb = 0; jb < n_len; jb += J_BLOCK) {
			const std::size_t block_len =
				(jb + J_BLOCK <= n_len) ? J_BLOCK : (n_len - jb);

			// 1) Load the current block of B[i][j] into the local buffer.
			//    This gives us a compact working set per row that the
			//    following k-loop can update without repeatedly hitting
			//    main memory for the destination elements.
			for (std::size_t jj = 0; jj < block_len; ++jj) {
				const std::size_t j = jb + jj;
				block_buf[jj] = B[noarr::idx<'i', 'j'>(i, j)];
			}

			// 2) Accumulate contributions from rows k > i:
			//
			//    For each k in (i+1 .. M-1):
			//      block_buf[j] += A[k][i] * B[k][j]  for all j in the block
			//
			//    A[k][i] does not depend on j, so we fetch it once per
			//    (i, k) pair and reuse it across the whole block.
			//    The order of k for each (i, j) remains strictly increasing
			//    (k = i+1, i+2, ...), exactly as in the original code.
			for (std::size_t k = i + 1; k < m_len; ++k) {
				const num_t a_ki = A[noarr::idx<'i', 'k'>(k, i)];

				for (std::size_t jj = 0; jj < block_len; ++jj) {
					const std::size_t j = jb + jj;
					const num_t Bkj = B[noarr::idx<'i', 'j'>(k, j)];
					block_buf[jj] += a_ki * Bkj;
				}
